 useEffect(()=>{if(!eligibleIds.includes(itemId))setItemId(eligibleIds[0]||'');},[eligibleIds.join('|'),itemId]);
 useEffect(()=>{setQuantity(available||1);setSubmitError('');},[itemId,available]);
