function ReturnAdditionalEvidenceAction({tx,role,onAction,refresh,busy}){const[ids,setIds]=useState([]),[note,setNote]=useState('');return <div className="action-form"><b>Additional return evidence</b><p>This does not reset or extend the supplier confirmation timer.</p><Field label="Note"><textarea value={note} onChange={e=>setNote(e.target.value)}/></Field><EvidenceInline purpose="OTHER" txId={tx.id} onUploaded={setIds}/><Button disabled={busy||!tx.return_id||!ids.length} onClick={async()=>{await onAction(`/returns/${tx.return_id}/additional-evidence`,{evidence_ids:ids,note});await refresh()}}>Add evidence</Button></div>}
